const C = [["photo","Noun. A photograph (passport/document photos, \"upload a photo\"). For generic files use the glossary term \"image\".",{"da":"foto","de":"Foto","es":"foto","fr":"photo","id":"foto","it":"foto","ko":"사진","ms":"foto","nl":"foto","no":"bilde","pl":"zdjęcie","pt":"foto","ro":"fotografie","sv":"foto","tr":"fotoğraf","uk":"фото","vi":"ảnh"}],["formats","Noun, plural of \"format\": image file formats (JPG, PNG, WebP…).",{"da":"formater","de":"Formate","es":"formatos","fr":"formats","id":"format","it":"formati","ko":"형식","ms":"format","nl":"formaten","no":"formater","pl":"formaty","pt":"formatos","ro":"formate","sv":"format","tr":"formatlar","uk":"формати","vi":"định dạng"}],["quality","Noun. Image quality (\"high quality\", \"without losing quality\").",{"da":"kvalitet","de":"Qualität","es":"calidad","fr":"qualité","id":"kualitas","it":"qualità","ko":"품질","ms":"kualiti","nl":"kwaliteit","no":"kvalitet","pl":"jakość","pt":"qualidade","ro":"calitate","sv":"kvalitet","tr":"kalite","uk":"якість","vi":"chất lượng"}],["device","Noun. The user's phone, tablet or computer (\"on any device\").",{"da":"enhed","de":"Gerät","es":"dispositivo","fr":"appareil","id":"perangkat","it":"dispositivo","ko":"기기","ms":"peranti","nl":"apparaat","no":"enhet","pl":"urządzenie","pt":"dispositivo","ro":"dispozitiv","sv":"enhet","th":"อุปกรณ์","tr":"cihaz","uk":"пристрій","vi":"thiết bị"}],["conversion","Noun. Image format conversion (convert tool).",{"es":"conversión","fr":"conversion","id":"konversi","it":"conversione","ko":"변환","ms":"penukaran","pl":"konwersja","uk":"конвертація","vi":"chuyển đổi"}],["Crop","Verb, button/tool name: crop an image. Buttons follow each guide (infinitive or imperative).",{"da":"Beskær","de":"Zuschneiden","es":"Recortar","it":"Ritaglia","ko":"자르기","ms":"Potong","nl":"Bijsnijden","no":"Beskjær","ro":"Decupează","sv":"Beskär","th":"ครอบตัด","uk":"Обрізати","vi":"Cắt"}],["resolution","Noun. Image resolution in pixels.",{"es":"resolución","id":"resolus