":"Chiều cao"}],["resizing","Noun. Image resizing.",{"fr":"redimensionnement","pl":"zmiana rozmiaru","pt":"redimensionamento","ro":"redimensionare","tr":"yeniden boyutlandırma","uk":"зміна розміру"}],["cropping","Noun. Image cropping.",{"da":"beskæring","es":"recorte","it":"ritaglio","no":"beskjæring","pt":"corte","ro":"decupare","sv":"beskärning","tr":"kırpma","uk":"обрізання","vi":"cắt"}],["Documents photo","Tool/menu name: photos for official documents (passport, ID, visa).",{"da":"Dokumentfoto","de":"Ausweisfoto","es":"Foto para documentos","fr":"Photo pour documents","id":"Foto dokumen","it":"Foto per documenti","ko":"증명 사진","ms":"Foto dokumen","no":"Dokumentfoto","pl":"Zdjęcie do dokumentów","pt":"Foto para documentos","sv":"Dokumentfoto","tr":"Belge fotoğrafı","uk":"Фото для документів","vi":"Ảnh tài liệu"}],["lighting","Noun. Lighting (photo requirements, studio lighting).",{"es":"iluminación","id":"pencahayaan","ko":"조명","ms":"pencahayaan","pl":"oświetlenie","pt":"iluminação","ro":"lumină","uk":"освітlення","vi":"ánh sáng"}]];
const NEW = C.map(function (c) { return { term: c[0], description: c[1] + SUF, caseSensitive: false, translatable: true, forbidden: false, tags: ['My Image', 'to_review'], translations: Object.keys(c[2]).map(function (k) { return { langId: ID[k], translation: c[2][k], description: '' }; }) }; });
const meta = []; const existing = {}; let complete = false;
for (const n of ['P1','P2','P3']) {
  const it = $(n).first().json; const b = it.body || {}; const h = it.headers || {}; const d = b.data || [];
  meta.push({ n: n, s: it.statusCode, cnt: d.length });
  for (const t of d) { existing[String(t.term || '').trim().toLowerCase()] = { id: t.id, term: t.term, tags: t.tags }; }
  if (!h['x-pagination-next-cursor']) { complete = true; break; }
}
const ok = complete && meta.every(function (m) { return m.s === 200; });
const dup = NEW.filter(function (t) { return existing[t.term.toLowerCase()]; }).map(function (t) { return existing[t.term.toLowerCase()]; });
const fresh = NEW.filter(function (t) { return !existing[t.term.toLowerCase()]; });
return [{ json: { meta: meta, existing_count: Object.keys(existing).length, duplicates: dup, fresh: fresh.map(function (t) { return t.term + ' (' + t.translations.length + ')'; }), proceed: ok && fresh.length > 0, body: { terms: fresh } } }];

// Replace any Latin letter sitting between Cyrillic letters (typo guard for uk).
const j = $input.first().json;
for (const t of j.body.terms) { for (const x of t.translations) { x.translation = x.translation.replace(/(?<=[\u0400-\u04FF])l(?=[\u0400-\u04FF])/g, '\u043b'); } }
const bad = [];
for (const t of j.body.terms) { for (const x of t.translations) { if (/[\u0400-\u04FF][A-Za-z]|[A-Za-z][\u0400-\u04FF]/.test(x.translation)) bad.push(t.term + ': ' + x.translation); } }
j.mixed_script_left = bad;
return [{ json: j }];
